const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    var aoiCenter = ee.Geometry.Point([39.4753, 13.4967]); // Mekele, Ethiopia
    var aoi = aoiCenter.buffer(15000).bounds(); // ~15 km radius box
    var scale = 1000; // coarse scale for reliable reductions
    var areaAOI_km2 = ee.Number(aoi.area(1)).divide(1e6).getInfo();

    // 2. Helpers: preprocessing
    function maskLandsat(img) {
      var qa = img.select('QA_PIXEL');
      var mask = qa.bitwiseAnd(1 << 1).eq(0) // dilated cloud
        .and(qa.bitwiseAnd(1 << 2).eq(0))   // cirrus
        .and(qa.bitwiseAnd(1 << 3).eq(0))   // cloud
        .and(qa.bitwiseAnd(1 << 4).eq(0))   // cloud shadow
        .and(qa.bitwiseAnd(1 << 5).eq(0));  // snow
      return img.updateMask(mask);
    }
    function prepLT05(img) {
      img = maskLandsat(img);
      var nir = img.select('SR_B4').multiply(0.0000275).add(-0.2);
      var swir1 = img.select('SR_B5').multiply(0.0000275).add(-0.2);
      return nir.addBands(swir1).rename(['nir', 'swir1']).copyProperties(img, ['system:time_start']);
    }
    function prepLT04(img) {
      img = maskLandsat(img);
      var nir = img.select('SR_B4').multiply(0.0000275).add(-0.2);
      var swir1 = img.select('SR_B5').multiply(0.0000275).add(-0.2);
      return nir.addBands(swir1).rename(['nir', 'swir1']).copyProperties(img, ['system:time_start']);
    }
    function prepLC08(img) {
      img = maskLandsat(img);
      var nir = img.select('SR_B5').multiply(0.0000275).add(-0.2);
      var swir1 = img.select('SR_B6').multiply(0.0000275).add(-0.2);
      return nir.addBands(swir1).rename(['nir', 'swir1']).copyProperties(img, ['system:time_start']);
    }
    function prepLC09(img) {
      img = maskLandsat(img);
      var nir = img.select('SR_B5').multiply(0.0000275).add(-0.2);
      var swir1 = img.select('SR_B6').multiply(0.0000275).add(-0.2);
      return nir.addBands(swir1).rename(['nir', 'swir1']).copyProperties(img, ['system:time_start']);
    }
    function buildEarlyCol(start, end, geom) {
      var col5 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2').filterDate(start, end).filterBounds(geom).map(prepLT05);
      var col4 = ee.ImageCollection('LANDSAT/LT04/C02/T1_L2').filterDate(start, end).filterBounds(geom).map(prepLT04);
      return col5.merge(col4);
    }
    function buildLateCol(start, end, geom) {
      var col9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').filterDate(start, end).filterBounds(geom).map(prepLC09);
      var col8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterDate(start, end).filterBounds(geom).map(prepLC08);
      return col9.merge(col8);
    }
    function computeNDBIComposite(col, geom) {
      var med = col.median().clip(geom);
      return med.expression('(swir1 - nir) / (swir1 + nir)', { swir1: med.select('swir1'), nir: med.select('nir') }).rename('ndbi');
    }
    function otsuFromHistogram(histDict) {
      var hist = ee.Dictionary(histDict);
      var counts = ee.Array(hist.get('histogram'));
      var means = ee.Array(hist.get('bucketMeans'));
      var total = ee.Number(counts.reduce('sum', [0]).get([0]));
      var sum = ee.Number(counts.multiply(means).reduce('sum', [0]).get([0]));
      var omega = counts.cumsum(0).divide(total);
      var mu = counts.multiply(means).cumsum(0).divide(total);
      var muTotal = sum.divide(total);
      var one = omega.multiply(0).add(1);
      var denom = omega.multiply(one.subtract(omega)).add(1e-10);
      var sigmaB2 = muTotal.multiply(omega).subtract(mu).pow(2).divide(denom);
      var sigmaList = ee.List(sigmaB2.toList());
      var meansList = ee.List(means.toList());
      var maxSigma = sigmaList.reduce(ee.Reducer.max());
      var maxIdx = sigmaList.indexOf(maxSigma);
      return ee.Number(meansList.get(maxIdx));
    }
    function metricsForYear(year, mode, geom) {
      var start = ee.Date.fromYMD(year, 1, 1);
      var end = ee.Date.fromYMD(year, 12, 31);
      var col = mode === 'early' ? buildEarlyCol(start, end, geom) : buildLateCol(start, end, geom);
      var size1 = col.size();
      // Fallback: widen date window by +1 year if empty
      col = ee.ImageCollection(ee.Algorithms.If(size1.gt(0), col, (mode === 'early'
        ? buildEarlyCol(start, end.advance(1, 'year'), geom)
        : buildLateCol(start, end.advance(1, 'year'), geom)
      )));
      var size = ee.Number(col.size());
      return ee.Dictionary({
        size: size,
        start: start.format('YYYY-MM-dd'),
        end: ee.Algorithms.If(size1.gt(0), end.format('YYYY-MM-dd'), end.advance(1, 'year').format('YYYY-MM-dd')),
        ndbi: computeNDBIComposite(col, geom)
      });
    }
    function summarizeYear(year, mode, geom, label) {
      var m = metricsForYear(year, mode, geom);
      var size = ee.Number(m.get('size'));
      var startStr = m.get('start');
      var endStr = m.get('end');
      var ndbi = ee.Image(m.get('ndbi'));
      var validPx = ee.Number(ndbi.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geom,
        scale: scale,
        maxPixels: 1e9,
        bestEffort: true
      }).get('ndbi'));
      var totalPx = ee.Number(ee.Image(1).reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geom,
        scale: scale,
        maxPixels: 1e9,
        bestEffort: true
      }).get('constant'));
      var cloudFreePct = ee.Algorithms.If(totalPx.neq(0), ee.Number(validPx).divide(totalPx).multiply(100), ee.Number(0));
      var hist = ndbi.reduceRegion({
        reducer: ee.Reducer.histogram({ maxBuckets: 128, minBucketWidth: 1e-3 }),
        geometry: geom,
        scale: scale,
        maxPixels: 1e9,
        bestEffort: true
      }).get('ndbi');
      var thresh = ee.Algorithms.If(hist, otsuFromHistogram(hist), null);
      var built = ee.Image(ee.Algorithms.If(thresh, ndbi.gt(ee.Number(thresh)), ndbi.updateMask(ndbi.eq(0)).rename('ndbi'))); // dummy if missing threshold
      var areaKm2 = ee.Image.pixelArea().divide(1e6).updateMask(built).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geom,
        scale: scale,
        maxPixels: 1e9,
        bestEffort: true
      }).get('area');
      return {
        label: label,
        size: size.getInfo(),
        start: startStr.getInfo(),
        end: endStr.getInfo(),
        validPx: validPx ? validPx.getInfo() : 0,
        totalPx: totalPx ? totalPx.getInfo() : 0,
        cloudFreePct: cloudFreePct ? ee.Number(cloudFreePct).getInfo() : 0,
        thresh: thresh !== null ? ee.Number(thresh).getInfo() : null,
        areaKm2: areaKm2 !== null ? ee.Number(areaKm2).getInfo() : null
      };
    }

    // 3. Data Acquisition & Check
    var stats1984 = summarizeYear(1984, 'early', aoi, '1984');
    if (stats1984.size === 0) {
      console.log('1984 Images: 0');
      console.log('C1');
      return;
    }
    var stats2025 = summarizeYear(2025, 'late', aoi, '2025');
    if (stats2025.size === 0) {
      console.log('2025 Images: 0');
      console.log('C1');
      return;
    }

    // 4. Processing validation (C2 / C3 checks)
    if (stats1984.validPx === 0 || stats2025.validPx === 0) {
      console.log(`Valid Pixels - 1984: ${stats1984.validPx}, 2025: ${stats2025.validPx}`);
      console.log('C2');
      return;
    }
    if (stats1984.thresh === null || stats2025.thresh === null ||
        stats1984.areaKm2 === null || stats2025.areaKm2 === null) {
      console.log('Calculation failure (null threshold or area).');
      console.log('C3');
      return;
    }
    // Sanity check: areas should be within AOI
    if (stats1984.areaKm2 < 0 || stats2025.areaKm2 < 0 ||
        stats1984.areaKm2 > areaAOI_km2 * 1.05 || stats2025.areaKm2 > areaAOI_km2 * 1.05 ||
        isNaN(stats1984.areaKm2) || isNaN(stats2025.areaKm2)) {
      console.log('Calculation failure (invalid area results).');
      console.log('C3');
      return;
    }

    // 5. Output concise evidence and final answer
    console.log(`AOI ~15 km buffer area (km²): ${areaAOI_km2.toFixed(1)}`);
    console.log(`1984 Images: ${stats1984.size} (${stats1984.start} to ${stats1984.end})`);
    console.log(`2025 Images: ${stats2025.size} (${stats2025.start} to ${stats2025.end})`);
    console.log(`1984 Valid px (1km): ${stats1984.validPx}/${stats1984.totalPx} (${stats1984.cloudFreePct.toFixed(1)}% cloud-free)`);
    console.log(`2025 Valid px (1km): ${stats2025.validPx}/${stats2025.totalPx} (${stats2025.cloudFreePct.toFixed(1)}% cloud-free)`);
    console.log(`1984 Otsu NDBI threshold: ${stats1984.thresh.toFixed(3)}`);
    console.log(`2025 Otsu NDBI threshold: ${stats2025.thresh.toFixed(3)}`);
    console.log(`1984 Urban area (km²): ${stats1984.areaKm2.toFixed(2)}`);
    console.log(`2025 Urban area (km²): ${stats2025.areaKm2.toFixed(2)}`);
    var diff = stats2025.areaKm2 - stats1984.areaKm2;
    var ratio = stats1984.areaKm2 > 0 ? (stats2025.areaKm2 / stats1984.areaKm2) : null;
    console.log(`Change (km²): ${diff.toFixed(2)}${ratio ? ` (x${ratio.toFixed(2)})` : ''}`);

    // Final Answer: A if increased, B otherwise
    console.log(diff > 0 ? 'A' : 'B');
  } catch (err) {
    console.log('Error encountered.');
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

